import json
from pathlib import Path
P=Path(__file__).resolve().parents[1]/'data'
def load(n):return json.loads((P/f'{n}.json').read_text())
def save(n,d):(P/f'{n}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
base='https://zombi-ferma.ucoz.net/news/'
rows=[('paskhalnye-yaytsa-kollektsiya-news','Пасхальные яйца и корзиночки — историческая акция','2015-04-04-177','zombi_ferma_paskhalnaja_kollekcija',{'Описание':'Источник предлагает собрать 14 пасхальных яиц и 3 корзиночки-ценности. Названия предметов и награда за весь набор в тексте не указаны.','Получение':'Часть набора можно выиграть в праздничных яйцах дома, часть — в рулетках у друзей. Если подарить другу 1 Пасхальный пряник, ему придёт случайное яйцо с начинкой.','Оговорка':'Праздничный набор не следует автоматически отождествлять с обычной обмениваемой коллекцией из пяти предметов.'}),('don-sanches-30-ezhednevnykh-kvestov','Байки Дона Санчеса — ежедневные квесты','2016-07-10-197','zombi_ferma_besplatnaja_lapsha_na_vse_ushi',{'Содержание':'Историческая заметка описывает байки Дона Санчеса Зомбиньё и 30 ежедневных квестов.','Ограничение':'Каждое задание было доступно 24 часа; по заметке второго шанса пройти его не было.','Награды':'За поручения обещаны билеты в кино; число билетов и условия каждого задания не приведены.'}),('ekolog-goda-uborka-aktsiya','Эколог года — уборка и ежедневные задания','2016-07-10-202','zombi_ferma_ehkolog_goda',{'Событие':'Десятидневная генеральная уборка: переработка мусора с помощью Дворника и получение призов.','Задания':'Ежедневно появлялся новый квест, действующий одни сутки; в награду за квесты можно было получить купоны на аренду инвентаря дворника.','Ограничение':'Статья не содержит перечня квестов, конкретного содержимого призов или условий получения купонов.'})]
u=load('updates')
for slug,name,dt,part,fields in rows:
 url=f'{base}{part}/{dt}'; e=next((x for x in u if x['slug']==slug),None)
 if e is None:
  e={'name':name,'slug':slug,'category':'updates','type':'Историческое событие','purchase':'нет данных','sale':'нет данных','obtain':'нет данных','use':'нет данных','features':'нет данных','versions':'браузерная социальная версия; сеть и дата обновления не установлены','sources':[],'image':None,'links':[],'event':'Историческая акция; актуальность не установлена','prior_records':[]};u.append(e)
 rec={'original_id':'ucoz-news-'+dt.split('-')[-1],'original_category':'Историческая новость','version':'браузерная социальная версия; сеть не указана','date':dt[:10]+' — дата публикации копии, не обязательно дата обновления','fields':fields,'confidence':'Фанатская публикация, возможна перепечатка; дата первичного сообщения и независимость от других источников неизвестны. Не считать действующим предложением.'}
 e['prior_records']=[x for x in e['prior_records'] if x.get('original_id')!=rec['original_id']]+[rec]
 if not any(s['url']==url for s in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная историческая новость'})
save('updates',u)
def enrich(cat,name,id,part,date,fields):
 d=load(cat);m=[x for x in d if x['name']==name];assert len(m)==1;e=m[0];url=base+part+'/'+date
 r={'original_id':'ucoz-news-'+id,'original_category':'Историческая новость','version':'социальная браузерная версия; сеть не указана','date':date[:10]+' — дата публикации копии; не обязательно дата события','fields':fields,'confidence':'Фанатская публикация, возможно перепечатана. Даты и действующие условия необходимо проверить.'}
 e['prior_records']=[x for x in e.get('prior_records',[]) if x.get('original_id')!=r['original_id']]+[r]
 if not any(x['url']==url for x in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная историческая новость'})
 save(cat,d)
enrich('zombies','Дворник Афанасий','198','zombi_ferma_afonja_speshit_na_pomoshh','2016-07-10-198',{'Летний дворник':'В исторической заметке летний Афанасий каждые 3 часа находил кротовую нору; друзья могли помочь отлавливать крота, за что обещаны бонусы. Состав бонусов не указан.','Оговорка':'Не доказано, что летний вариант имел те же цены и правила, что осенний дворник 2015 года.'})
enrich('locations','Солнечный остров','181','zombi_ferma_zasukha_anons_obnovlenija','2015-04-04-181',{'Анонс «Засуха»':'По заметке, летать на остров можно в течение 30 дней после первого прибытия; оставаться на нём можно без указанного ограничения. Источник советует не забыть работников до окончания срока перелётов.','Водный канал':'Детали канала производятся в Тереме на Солнечном острове; за преодоление трудностей обещана Золотая Фемида. Конкретные рецепты и условия получения не указаны.','Даты':'Страница датирована апрелем 2015 года, но текст говорит о летней квестовой линейке; дата копии сама по себе не устанавливает дату события.'})
s=load('sources')
for e in s:
 if e['number']==11 and 'Эколог года' not in e['summary']:e['summary']+=' Дополнительно прочитаны новости о пасхальном наборе, 30 заданиях Дона Санчеса, летнем Афанасии, уборке «Эколог года» и анонсе «Засуха»; даты копий не обязательно соответствуют датам событий.'
save('sources',s)
print('3 события добавлены или обновлены, 2 карточки дополнены')
